package jp.amaro.survival.command;
import org.bukkit.entity.Player;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.lang.reflect.Proxy;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.jupiter.api.Assertions.*;
class TestAdminAuthorizerTest {@TempDir Path temp;@Test void onlyConfiguredPlayerBecomesOpAndUuidIsPersisted()throws Exception{Path file=temp.resolve("test-admin.properties");Files.writeString(file,"player-name=Amaro\nplayer-uuid=\n");TestAdminAuthorizer a=new TestAdminAuthorizer(file);AtomicBoolean op=new AtomicBoolean();UUID id=UUID.randomUUID();Player configured=player("Amaro",id,op),other=player("Other",UUID.randomUUID(),new AtomicBoolean());a.bootstrap(other);assertFalse(other.isOp());a.bootstrap(configured);assertTrue(op.get());assertTrue(Files.readString(file).contains(id.toString()));}@Test void missingConfigurationDoesNotGrantOp(){AtomicBoolean op=new AtomicBoolean();new TestAdminAuthorizer(temp.resolve("missing.properties")).bootstrap(player("Amaro",UUID.randomUUID(),op));assertFalse(op.get());}private static Player player(String name,UUID id,AtomicBoolean op){return(Player)Proxy.newProxyInstance(Player.class.getClassLoader(),new Class[]{Player.class},(p,m,args)->switch(m.getName()){case"getName"->name;case"getUniqueId"->id;case"isOp"->op.get();case"setOp"->{op.set((boolean)args[0]);yield null;}case"hasPermission"->false;default->m.getReturnType()==boolean.class?false:null;});}}
